// Package calc evaluates 64-bit signed integer arithmetic expressions.
//
// The evaluator is an iterative operator-precedence (shunting-yard) parser
// with explicit stacks, so arbitrarily deep nesting cannot exhaust the
// goroutine stack.
package calc

import (
	"errors"
	"math"
)

// Errors reported by Evaluate.
var (
	ErrSyntax    = errors.New("syntax error")
	ErrDivByZero = errors.New("division by zero")
	ErrOverflow  = errors.New("integer overflow")
)

// op is an operator kept on the evaluator's operator stack.
type op byte

const (
	opAdd    op = '+'
	opSub    op = '-'
	opMul    op = '*'
	opDiv    op = '/'
	opRem    op = '%'
	opNeg    op = 'n'
	opLParen op = '('
)

// precedence returns the binding strength of o; '(' never pops.
func (o op) precedence() int {
	switch o {
	case opAdd, opSub:
		return 1
	case opMul, opDiv, opRem:
		return 2
	case opNeg:
		return 3
	default:
		return 0
	}
}

// Evaluator evaluates expressions, reusing its internal stacks between
// calls to avoid repeated allocation. The zero value is ready to use.
// An Evaluator is not safe for concurrent use.
type Evaluator struct {
	values []int64
	ops    []op
}

// Evaluate parses and evaluates expr according to the grammar:
//
//	expr    := term    (('+' | '-') term)*
//	term    := unary   (('*' | '/' | '%') unary)*
//	unary   := '-' unary | primary
//	primary := NUMBER | '(' expr ')'
//	NUMBER  := [0-9]+
//
// Spaces and tabs may appear between tokens.
func (e *Evaluator) Evaluate(expr []byte) (int64, error) {
	e.values = e.values[:0]
	e.ops = e.ops[:0]

	expectOperand := true
	for i := 0; ; {
		for i < len(expr) && isBlank(expr[i]) {
			i++
		}
		if i == len(expr) {
			break
		}

		c := expr[i]
		if expectOperand {
			switch {
			case isDigit(c):
				var v int64
				for ; i < len(expr) && isDigit(expr[i]); i++ {
					d := int64(expr[i] - '0')
					if v > (math.MaxInt64-d)/10 {
						return 0, ErrOverflow
					}
					v = v*10 + d
				}
				e.values = append(e.values, v)
				expectOperand = false
			case c == '-':
				e.ops = append(e.ops, opNeg)
				i++
			case c == '(':
				e.ops = append(e.ops, opLParen)
				i++
			default:
				return 0, ErrSyntax
			}
			continue
		}

		switch o := op(c); o {
		case opAdd, opSub, opMul, opDiv, opRem:
			if err := e.reduce(o.precedence()); err != nil {
				return 0, err
			}
			e.ops = append(e.ops, o)
			expectOperand = true
		case ')':
			if err := e.reduce(0); err != nil {
				return 0, err
			}
			if len(e.ops) == 0 {
				return 0, ErrSyntax // unmatched ')'
			}
			e.ops = e.ops[:len(e.ops)-1] // discard '('
		default:
			return 0, ErrSyntax
		}
		i++
	}

	if expectOperand {
		return 0, ErrSyntax
	}
	if err := e.reduce(0); err != nil {
		return 0, err
	}
	if len(e.ops) != 0 || len(e.values) != 1 {
		return 0, ErrSyntax // unmatched '('
	}
	return e.values[0], nil
}

// reduce pops and applies operators whose precedence is at least minPrec.
func (e *Evaluator) reduce(minPrec int) error {
	for len(e.ops) > 0 {
		top := e.ops[len(e.ops)-1]
		if top == opLParen || top.precedence() < minPrec {
			return nil
		}
		e.ops = e.ops[:len(e.ops)-1]
		if err := e.apply(top); err != nil {
			return err
		}
	}
	return nil
}

// apply applies o to the operand(s) on top of the value stack.
func (e *Evaluator) apply(o op) error {
	n := len(e.values)
	if o == opNeg {
		if n < 1 {
			return ErrSyntax
		}
		v, err := neg(e.values[n-1])
		if err != nil {
			return err
		}
		e.values[n-1] = v
		return nil
	}
	if n < 2 {
		return ErrSyntax
	}
	a, b := e.values[n-2], e.values[n-1]
	var (
		r   int64
		err error
	)
	switch o {
	case opAdd:
		r, err = add(a, b)
	case opSub:
		r, err = sub(a, b)
	case opMul:
		r, err = mul(a, b)
	case opDiv:
		r, err = div(a, b)
	case opRem:
		r, err = rem(a, b)
	default:
		return ErrSyntax
	}
	if err != nil {
		return err
	}
	e.values = e.values[:n-1]
	e.values[n-2] = r
	return nil
}

func isBlank(c byte) bool { return c == ' ' || c == '\t' }
func isDigit(c byte) bool { return '0' <= c && c <= '9' }

// IsBlank reports whether line consists only of spaces and tabs.
func IsBlank(line []byte) bool {
	for _, c := range line {
		if !isBlank(c) {
			return false
		}
	}
	return true
}

package calc

import "math"

// Checked arithmetic: each function reports ErrOverflow when the exact
// result does not fit in an int64, and ErrDivByZero for a zero divisor.

func add(a, b int64) (int64, error) {
	if (b > 0 && a > math.MaxInt64-b) || (b < 0 && a < math.MinInt64-b) {
		return 0, ErrOverflow
	}
	return a + b, nil
}

func sub(a, b int64) (int64, error) {
	if (b < 0 && a > math.MaxInt64+b) || (b > 0 && a < math.MinInt64+b) {
		return 0, ErrOverflow
	}
	return a - b, nil
}

func mul(a, b int64) (int64, error) {
	if a == 0 || b == 0 {
		return 0, nil
	}
	r := a * b
	if r/b != a || (a == -1 && b == math.MinInt64) || (b == -1 && a == math.MinInt64) {
		return 0, ErrOverflow
	}
	return r, nil
}

func div(a, b int64) (int64, error) {
	if b == 0 {
		return 0, ErrDivByZero
	}
	if a == math.MinInt64 && b == -1 {
		return 0, ErrOverflow
	}
	return a / b, nil
}

// rem returns the remainder of truncated division; its sign follows a.
// MinInt64 % -1 is 0 (Go defines this without overflow).
func rem(a, b int64) (int64, error) {
	if b == 0 {
		return 0, ErrDivByZero
	}
	return a % b, nil
}

func neg(a int64) (int64, error) {
	if a == math.MinInt64 {
		return 0, ErrOverflow
	}
	return -a, nil
}

// Command calc reads one integer expression per line from standard input
// and prints its value, or "error" if it cannot be evaluated.
package main

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"

	"calc/internal/calc"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "calc:", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	in := bufio.NewReaderSize(r, 64*1024)
	out := bufio.NewWriterSize(w, 64*1024)

	var (
		ev   calc.Evaluator
		line []byte
		num  []byte
	)
	for {
		var err error
		line, err = readLine(in, line[:0])
		if err != nil && !errors.Is(err, io.EOF) {
			return err
		}
		if !calc.IsBlank(line) {
			if v, evalErr := ev.Evaluate(line); evalErr != nil {
				out.WriteString("error\n")
			} else {
				num = strconv.AppendInt(num[:0], v, 10)
				num = append(num, '\n')
				out.Write(num)
			}
		}
		if err != nil { // io.EOF
			break
		}
	}
	return out.Flush()
}

// readLine appends the next line (without its '\n') to buf. It returns
// io.EOF when input ends; buf may still hold a final unterminated line.
func readLine(r *bufio.Reader, buf []byte) ([]byte, error) {
	for {
		chunk, err := r.ReadSlice('\n')
		buf = append(buf, chunk...)
		switch {
		case err == nil:
			return buf[:len(buf)-1], nil
		case errors.Is(err, bufio.ErrBufferFull):
			continue
		default:
			return buf, err
		}
	}
}
